// Written with the help of Claude
// AI Usage Note: generated by Claude; every case checked against PoliteHttpClient by running the tests.
import assert from 'node:assert/strict';
import { createServer, type Server } from 'node:http';
import type { AddressInfo } from 'node:net';
import { after, before, describe, mock, test } from 'node:test';
import { Logger } from '@nestjs/common';
import { PoliteHttpClient } from '../../dist/infra/providers/http-client.js';

// REL-003: a provider page that fails now and then is retried, not lost.
describe('PoliteHttpClient', () => {
  let server: Server;
  let baseUrl: string;
  const received: { path: string | undefined; userAgent: string | undefined; at: number }[] = [];
  let failuresLeft = 0;

  before(async () => {
    server = createServer((req, res) => {
      received.push({ path: req.url, userAgent: req.headers['user-agent'], at: Date.now() });
      if (req.url === '/flaky' && failuresLeft > 0) {
        failuresLeft--;
        res.writeHead(503).end();
        return;
      }
      res.writeHead(req.url === '/missing' ? 404 : 200).end(`page ${req.url}`);
    });
    await new Promise<void>((resolve) => server.listen(0, resolve));
    baseUrl = `http://localhost:${(server.address() as AddressInfo).port}`;
    mock.method(Logger.prototype, 'warn', () => {});
  });

  after(async () => {
    mock.restoreAll();
    await new Promise<void>((resolve) => server.close(() => resolve()));
  });

  const client = (options: Partial<ConstructorParameters<typeof PoliteHttpClient>[0]> = {}) =>
    new PoliteHttpClient({ userAgent: 'NearbyImport/test', intervalMs: 0, backoffMs: 1, ...options });

  test('sends the User-Agent and returns the page', async () => {
    received.length = 0;

    const response = await client().get(`${baseUrl}/concerts/`);

    assert.deepEqual([response.status, response.text], [200, 'page /concerts/']);
    assert.equal(received[0]?.userAgent, 'NearbyImport/test');
  });

  test('waits the interval between two requests', async () => {
    received.length = 0;
    const polite = client({ intervalMs: 150 });

    await Promise.all([polite.get(`${baseUrl}/a`), polite.get(`${baseUrl}/b`)]);

    // Measured where the server receives them, so the first connection's setup can eat into the gap a little.
    const [first, second] = received;
    assert.ok(first && second && second.at - first.at >= 100, `${second?.at} - ${first?.at}`);
  });

  test('retries a 5xx answer and returns the page once it comes', async () => {
    received.length = 0;
    failuresLeft = 2;

    const response = await client().get(`${baseUrl}/flaky`);

    assert.equal(response.status, 200);
    assert.equal(received.length, 3);
  });

  test('returns a 404 at once, without retrying', async () => {
    received.length = 0;

    const response = await client().get(`${baseUrl}/missing`);

    assert.equal(response.status, 404);
    assert.equal(received.length, 1);
  });

  test('throws after the retries when the server cannot be reached', async () => {
    await assert.rejects(client({ retries: 1 }).get('http://localhost:1/unreachable'));
  });

  const disallowed = [
    { site: 'ArtWizard', paths: ['/api/', '/internal/', '/cdn-cgi/'], url: '/api/events' },
    { site: 'ArtWizard', paths: ['/api/', '/internal/', '/cdn-cgi/'], url: '/cdn-cgi/imagedelivery/x/public' },
    { site: 'Karabas', paths: ['/ajax.php'], url: '/ajax.php?action=events' },
  ];
  for (const { site, paths, url } of disallowed) {
    test(`refuses ${url}, disallowed by the robots.txt of ${site}, without sending it`, async () => {
      received.length = 0;

      await assert.rejects(client({ disallowedPaths: paths }).get(`${baseUrl}${url}`), /disallowed by robots\.txt/);

      assert.equal(received.length, 0);
    });
  }
});
